INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 24, 'theory', 'Quiz: libvirt and virsh');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 0, 'Which URI connects virsh to the system instance that manages the guests of all users?', '["qemu:///session", "qemu+ssh://localhost/session", "qemu:///system", "libvirt:///root"]', 2, 'qemu:///system is the system instance: it runs as root and manages the guests of all users. qemu:///session is a personal instance of an ordinary user.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 1, 'What does virsh destroy web01 do?', '["Forcibly stops the guest without touching the disks and the definition", "Deletes the domain definition and its disks", "Asks the guest to power off cleanly through ACPI", "Pauses the guest in memory"]', 0, 'destroy pulls the plug: the guest has no chance to react, but no volumes are deleted and a persistent domain can be started again. The polite request is shutdown.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 2, 'A domain XML has <memory>2097152</memory> with no unit attribute. How much memory is that?', '["Two mebibytes", "2097152 mebibytes", "Two million bytes", "Two gibibytes, because the default unit is the kibibyte"]', 3, 'Without unit the number is in kibibytes: 2097152 KiB = 2048 MiB = 2 GiB. That is why scripts convert the unit explicitly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 3, 'What does a NoCloud seed need for cloud-init to find it and treat the boot as the first one?', '["A disk with any label and a config.yaml file", "A filesystem labeled cidata and a meta-data file with an instance-id", "Only user-data: the guest creates meta-data itself", "A network card named cloud0"]', 1, 'It takes a vfat or ISO filesystem labeled cidata with the files in its root, and meta-data must have an instance-id: it tells the first boot. Changing the instance-id triggers configuration again.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 4, 'What happens if you delete a snapshot that has children with snapshot-delete and no extra options?', '["All the children are deleted", "The command refuses while children exist", "The snapshot''s changes are merged into its children", "The domain rolls back to the parent"]', 2, 'Without --children the deleted snapshot''s changes are merged into its children, which become children of its parent. To remove the whole branch you need --children.');
